// buildRegex builds the final regex from the configured patterns.
func buildRegex(cfg *Config) (*regexp.Regexp, error) {
	pats := cfg.Patterns
	// read pattern files
	for _, pf := range cfg.PatternFiles {
		var r io.Reader
		if pf == "-" {
			r = os.Stdin
		} else {
			f, err := os.Open(pf)
			if err != nil {
				return nil, err
			}
			defer f.Close()
			r = f
		}
		sc := bufio.NewScanner(r)
		sc.Buffer(make([]byte, 64*1024), 10*1024*1024)
		for sc.Scan() {
			pats = append(pats, sc.Text())
		}
	}
	if len(pats) == 0 {
		return nil, fmt.Errorf("ripgrep requires at least one pattern to execute a search")
	}

	// build alt
	out := make([]string, 0, len(pats))
	for _, p := range pats {
		if cfg.FixedStrings {
			p = regexp.QuoteMeta(p)
		}
		if cfg.WordRegexp {
			p = `(?:` + p + `)`
			p = `(?:^|\W)` + p + `(?:\W|$)`
		}
		if cfg.LineRegexp {
			p = `^(?:` + p + `)$`
		}
		out = append(out, p)
	}
	expr := strings.Join(out, "|")

	// case handling
	caseInsensitive := cfg.CaseInsensitive
	if cfg.SmartCase && !cfg.CaseSensitive && !cfg.CaseInsensitive {
		if !hasUppercase(expr) {
			caseInsensitive = true
		}
	}
	var prefix string
	if caseInsensitive {
		prefix = "(?i)"
	} else {
		prefix = ""
	}
	if cfg.Multiline {
		prefix = prefix + "(?s:)"
		if !cfg.MultilineDotall {
			// default . does not match newline - but in multiline, we still have (?s) for dotall; leave alone.
		}
	}
	full := prefix + expr

	re, err := regexp.Compile(full)
	if err != nil {
		// wrap error
		return nil, fmt.Errorf("regex parse error: %v", err)
	}
	// verify via syntax Parse
	_ = syntax.Perl
	return re, nil
}

func hasUppercase(s string) bool {
	for _, r := range s {
		if r >= 'A' && r <= 'Z' {
			return true
		}
	}
	return false
}

// runSearch performs the main search.
func runSearch(cfg *Config) (int, error) {
	re, err := buildRegex(cfg)
	if err != nil {
		return ExitError, err
	}

	paths := cfg.Paths

	// stdin detection
	useStdin := false
	if len(paths) == 0 {
		// if stdin is piped (not a tty), use stdin
		if isStdinPipe() {
			useStdin = true
		} else {
			paths = []string{"."}
		}
	}

	// Figure out output mode
	stdoutIsTTY := isStdoutTTY()
	if !cfg.ColorSet {
		if stdoutIsTTY {
			cfg.Color = "auto"
		} else {
			cfg.Color = "never"
		}
	}
	useColor := false
	switch cfg.Color {
	case "always", "ansi":
		useColor = true
	case "auto":
		useColor = stdoutIsTTY
	case "never":
		useColor = false
	}

	// heading
	if cfg.Heading == 0 {
		if stdoutIsTTY {
			cfg.Heading = 1
		} else {
			cfg.Heading = -1
		}
	}

	// line number
	if !cfg.ShowLineNumberSet {
		// default: on when heading is used or tty
		if stdoutIsTTY {
			cfg.ShowLineNumber = true
		}
	}

	// with filename
	if !cfg.WithFilenameSet {
		if useStdin {
			cfg.WithFilename = false
		} else if len(paths) == 1 {
			// single file => no filename; single dir => yes
			fi, err := os.Stat(paths[0])
			if err == nil && fi.Mode().IsRegular() {
				cfg.WithFilename = false
			} else {
