}

func searchPath(s *Searcher, root string, isFirst bool) (bool, error) {
	fi, err := os.Stat(root)
	if err != nil {
		return false, err
	}
	if fi.Mode().IsRegular() {
		f, err := os.Open(root)
		if err != nil {
			return false, err
		}
		defer f.Close()
		return s.SearchReader(f, root, true)
	}
	if !fi.IsDir() {
		return false, nil
	}
	// walk
	return walkAndSearch(s, root)
}

func walkAndSearch(s *Searcher, root string) (bool, error) {
	cfg := s.Cfg
	type entry struct {
		path string
		info os.FileInfo
	}
	var results []entry
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		name := info.Name()
		// Skip hidden unless requested
		if path != root && strings.HasPrefix(name, ".") && !cfg.Hidden && cfg.Unrestricted < 1 {
			if info.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		// Depth
		if cfg.HasMaxDepth {
			rel, _ := filepath.Rel(root, path)
			depth := 0
			if rel != "." {
				depth = strings.Count(rel, string(os.PathSeparator)) + 1
			}
			if depth > cfg.MaxDepth {
				if info.IsDir() {
					return filepath.SkipDir
				}
				return nil
			}
		}
		if info.IsDir() {
			return nil
		}
		// Glob filter
		if len(cfg.Glob) > 0 || len(cfg.IGlob) > 0 {
			if !matchGlobs(cfg, path, name) {
				return nil
			}
		}
		results = append(results, entry{path, info})
		return nil
	})
	if err != nil {
		return false, err
	}
	// sort based on cfg.Sort
	sortEntries(results, cfg)

	found := false
	for _, e := range results {
		f, err := os.Open(e.path)
		if err != nil {
			if !cfg.NoMessages {
				fmt.Fprintf(os.Stderr, "rg: %s: %v\n", e.path, err)
			}
			continue
		}
		// Normalize path: if root == ".", strip leading "./"
		displayPath := e.path
		if root == "." && strings.HasPrefix(displayPath, "./") {
			displayPath = displayPath[2:]
		}
		// Quickly detect if binary
		isBin, _ := isBinaryFile(f)
		f.Seek(0, io.SeekStart)
		if isBin && cfg.Unrestricted < 3 {
			f.Close()
			continue
		}
		got, _ := s.SearchReader(f, displayPath, true)
		f.Close()
		if got {
			found = true
			if cfg.Quiet {
				return true, nil
			}
		}
	}
	return found, nil
}

func sortEntries(results []struct {
	path string
	info os.FileInfo
}, cfg *Config) {
	// no-op in minimal impl
	_ = sort.Slice
	switch cfg.Sort {
	case "path":
		sort.Slice(results, func(i, j int) bool { return results[i].path < results[j].path })
	case "none":
	}
	switch cfg.SortR {
	case "path":
		sort.Slice(results, func(i, j int) bool { return results[i].path > results[j].path })
	}
}

func matchGlobs(cfg *Config, path, name string) bool {
	// Very basic glob: only support simple filename globs and '!' prefix for excl.
	include := []string{}
	exclude := []string{}
	for _, g := range cfg.Glob {
		if strings.HasPrefix(g, "!") {
			exclude = append(exclude, g[1:])
		} else {
			include = append(include, g)
		}
	}
	for _, g := range cfg.IGlob {
		if strings.HasPrefix(g, "!") {
			exclude = append(exclude, strings.ToLower(g[1:]))
		} else {
			include = append(include, strings.ToLower(g))
		}
	}
	// excludes
	for _, g := range exclude {
		if globMatch(g, path) || globMatch(g, name) {
			return false
		}
	}
	if len(include) == 0 {
		return true
	}
	for _, g := range include {
		if globMatch(g, path) || globMatch(g, name) {
			return true
		}
	}
	return false
}

func globMatch(pattern, s string) bool {
	// Use filepath.Match
	if strings.Contains(pattern, "/") {
		ok, _ := filepath.Match(pattern, s)
		return ok
	}
	// basename match
	base := filepath.Base(s)
	ok, _ := filepath.Match(pattern, base)
	return ok
}

func isBinaryFile(f *os.File) (bool, error) {
	// Read first 8KB and look for NUL
	buf := make([]byte, 8192)
	n, _ := f.Read(buf)
	buf = buf[:n]
	return bytes.IndexByte(buf, 0) >= 0, nil
}

// Searcher holds search state.
type Searcher struct {
	Cfg      *Config
	Re       *regexp.Regexp
	Out      *bufio.Writer
	UseColor bool

	// For --heading: track whether we printed any file, so we can add blank line
	printedAny bool
}

func (s *Searcher) SearchReader(r io.Reader, displayPath string, isFile bool) (bool, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return false, err
	}
	// line terminator
	lineSep := byte('\n')
	if s.Cfg.NullData {
		lineSep = 0
	}

	// Split lines
	var lines [][]byte
	start := 0
	for i := 0; i < len(data); i++ {
		if data[i] == lineSep {
			lines = append(lines, data[start:i])
			start = i + 1
		}
	}
	if start < len(data) {
		lines = append(lines, data[start:])
	}
	// binary detection
	// (already done at walk level, but for stdin/args, do basic skip)

	cfg := s.Cfg
	// Compute matches per line
	type matchInfo struct {
		line     int
		col      int
		byteOff  int
		data     []byte
		matches  [][]int
	}
	var matches []matchInfo
	offset := 0
	for idx, line := range lines {
		hit := false
		var ms [][]int
		if cfg.InvertMatch {
			hit = !s.Re.Match(line)
		} else {
			ms = s.Re.FindAllIndex(line, -1)
			hit = len(ms) > 0
		}
		if hit {
			col := 0
			if len(ms) > 0 {
				col = ms[0][0] + 1
			}
			matches = append(matches, matchInfo{
				line:    idx + 1,
				col:     col,
				byteOff: offset,
				data:    line,
				matches: ms,
			})
		}
		offset += len(line) + 1
	}

	if cfg.FilesWithMatches {
		if len(matches) > 0 {
			s.Out.WriteString(displayPath)
			if cfg.Null {
				s.Out.WriteByte(0)
			} else {
				s.Out.WriteByte('\n')
			}
			return true, nil
		}
		return false, nil
	}
	if cfg.FilesWithoutMatch {
		if len(matches) == 0 {
			s.Out.WriteString(displayPath)
			if cfg.Null {
				s.Out.WriteByte(0)
			} else {
				s.Out.WriteByte('\n')
			}
			return false, nil // technically a "non-match" but ripgrep prints it
		}
		return len(matches) > 0, nil
	}
	if cfg.Quiet {
		return len(matches) > 0, nil
	}
	if cfg.Count {
		if len(matches) == 0 {
			return false, nil
		}
		total := 0
		if cfg.CountMatches {
			for _, m := range matches {
				total += len(m.matches)
				if total == 0 {
					total += 1
				}
			}
			// recompute properly:
			total = 0
			for _, m := range matches {
				if len(m.matches) > 0 {
					total += len(m.matches)
				} else {
					total++
				}
			}
		} else {
			total = len(matches)
		}
		if cfg.WithFilename {
			if cfg.Heading == 1 {
				s.printHeading(displayPath)
			} else {
				s.writePathPrefix(displayPath)
				s.Out.WriteString(cfg.FieldMatchSeparator)
			}
		}
		fmt.Fprintf(s.Out, "%d\n", total)
		if cfg.Heading == 1 && cfg.WithFilename {
			s.Out.WriteByte('\n')
		}
		return true, nil
	}

	if len(matches) == 0 {
		// Nothing to print for -A/-B/-C case if inverting etc.
		if cfg.HasMaxCount && cfg.MaxCount == 0 {
			return false, nil
		}
		return false, nil
	}

	// apply max-count
	if cfg.HasMaxCount {
		if int64(len(matches)) > cfg.MaxCount {
			matches = matches[:cfg.MaxCount]
		}
	}

	// Print heading if applicable
	printedHeading := false
	if cfg.Heading == 1 && cfg.WithFilename {
		if s.printedAny {
			s.Out.WriteByte('\n')
		}
		s.printHeading(displayPath)
		printedHeading = true
		s.printedAny = true
	}

	printed := make(map[int]bool)
	contextPrinted := false
	for mi, m := range matches {
		// Before-context
		if cfg.BeforeContext > 0 {
			start := m.line - cfg.BeforeContext
			if start < 1 {
				start = 1
			}
			// avoid printing twice
			for ln := start; ln < m.line; ln++ {
				if printed[ln] {
					continue
				}
				if contextPrinted && mi > 0 && ln == start && cfg.AfterContext+cfg.BeforeContext > 0 {
					// separator "--"
					if ln != matches[mi-1].line+1 && !printed[ln-1] {
						if cfg.Heading != 1 || !printedHeading {
							// ripgrep does print "--" separator; see logic
						}
					}
				}
				s.printLine(displayPath, ln, lines[ln-1], nil, 0, printedHeading, true)
				printed[ln] = true
			}
		}
		if !printed[m.line] {
			s.printLine(displayPath, m.line, m.data, m.matches, m.col, printedHeading, false)
			printed[m.line] = true
		}
		// After-context
		if cfg.AfterContext > 0 {
			endLine := m.line + cfg.AfterContext
			if endLine > len(lines) {
				endLine = len(lines)
			}
			for ln := m.line + 1; ln <= endLine; ln++ {
				if printed[ln] {
					continue
				}
				// Don't print if next match line begins
				if mi+1 < len(matches) && ln >= matches[mi+1].line {
					break
				}
				s.printLine(displayPath, ln, lines[ln-1], nil, 0, printedHeading, true)
				printed[ln] = true
				contextPrinted = true
			}
		}
	}

	return true, nil
}

