		if isBin && cfg.Unrestricted < 3 {
			f.Close()
			continue
		}
		got, _ := s.SearchReader(f, displayPath, true)
		f.Close()
		if got {
			found = true
			if cfg.Quiet {
				return true, nil
			}
		}
	}
	return found, nil
}

func sortEntries(results []struct {
	path string
	info os.FileInfo
}, cfg *Config) {
	// no-op in minimal impl
	_ = sort.Slice
