func matchGlobs(cfg *Config, path, name string) bool {
	// Very basic glob: only support simple filename globs and '!' prefix for excl.
	include := []string{}
	exclude := []string{}
	for _, g := range cfg.Glob {
		if strings.HasPrefix(g, "!") {
			exclude = append(exclude, g[1:])
		} else {
			include = append(include, g)
		}
	}
	for _, g := range cfg.IGlob {
		if strings.HasPrefix(g, "!") {
			exclude = append(exclude, strings.ToLower(g[1:]))
		} else {
			include = append(include, strings.ToLower(g))
		}
	}
	// excludes
	for _, g := range exclude {
		if globMatch(g, path) || globMatch(g, name) {
			return false
		}
	}
	if len(include) == 0 {
		return true
	}
	for _, g := range include {
		if globMatch(g, path) || globMatch(g, name) {
			return true
		}
	}
	return false
}

func globMatch(pattern, s string) bool {
	// Use filepath.Match
	if strings.Contains(pattern, "/") {
		ok, _ := filepath.Match(pattern, s)
		return ok
	}
	// basename match
	base := filepath.Base(s)
	ok, _ := filepath.Match(pattern, base)
	return ok
}

func isBinaryFile(f *os.File) (bool, error) {
	// Read first 8KB and look for NUL
	buf := make([]byte, 8192)
	n, _ := f.Read(buf)
	buf = buf[:n]
	return bytes.IndexByte(buf, 0) >= 0, nil
}

// Searcher holds search state.
type Searcher struct {
	Cfg      *Config
	Re       *regexp.Regexp
	Out      *bufio.Writer
	UseColor bool

	// For --heading: track whether we printed any file, so we can add blank line
	printedAny bool
}

func (s *Searcher) SearchReader(r io.Reader, displayPath string, isFile bool) (bool, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return false, err
	}
	// line terminator
	lineSep := byte('\n')
	if s.Cfg.NullData {
		lineSep = 0
	}

	// Split lines
	var lines [][]byte
	start := 0
	for i := 0; i < len(data); i++ {
		if data[i] == lineSep {
			lines = append(lines, data[start:i])
			start = i + 1
		}
	}
	if start < len(data) {
		lines = append(lines, data[start:])
	}
	// binary detection
	// (already done at walk level, but for stdin/args, do basic skip)

	cfg := s.Cfg
	// Compute matches per line
	type matchInfo struct {
		line     int
		col      int
		byteOff  int
		data     []byte
		matches  [][]int
	}
	var matches []matchInfo
	offset := 0
	for idx, line := range lines {
		hit := false
		var ms [][]int
		if cfg.InvertMatch {
			hit = !s.Re.Match(line)
		} else {
			ms = s.Re.FindAllIndex(line, -1)
			hit = len(ms) > 0
		}
		if hit {
			col := 0
			if len(ms) > 0 {
				col = ms[0][0] + 1
			}
			matches = append(matches, matchInfo{
				line:    idx + 1,
				col:     col,
				byteOff: offset,
				data:    line,
				matches: ms,
			})
		}
		offset += len(line) + 1
	}

	if cfg.FilesWithMatches {
		if len(matches) > 0 {
			s.Out.WriteString(displayPath)
			if cfg.Null {
				s.Out.WriteByte(0)
			} else {
				s.Out.WriteByte('\n')
			}
			return true, nil
		}
		return false, nil
	}
	if cfg.FilesWithoutMatch {
		if len(matches) == 0 {
			s.Out.WriteString(displayPath)
			if cfg.Null {
				s.Out.WriteByte(0)
			} else {
				s.Out.WriteByte('\n')
			}
			return false, nil // technically a "non-match" but ripgrep prints it
		}
		return len(matches) > 0, nil
	}
	if cfg.Quiet {
		return len(matches) > 0, nil
	}
	if cfg.Count {
		if len(matches) == 0 {
			return false, nil
		}
		total := 0
		if cfg.CountMatches {
			for _, m := range matches {
				total += len(m.matches)
				if total == 0 {
					total += 1
				}
			}
			// recompute properly:
			total = 0
			for _, m := range matches {
				if len(m.matches) > 0 {
					total += len(m.matches)
				} else {
					total++
				}
			}
		} else {
			total = len(matches)
		}
		if cfg.WithFilename {
			if cfg.Heading == 1 {
				s.printHeading(displayPath)
			} else {
				s.writePathPrefix(displayPath)
				s.Out.WriteString(cfg.FieldMatchSeparator)
			}
		}
		fmt.Fprintf(s.Out, "%d\n", total)
		if cfg.Heading == 1 && cfg.WithFilename {
			s.Out.WriteByte('\n')
		}
		return true, nil
	}

	if len(matches) == 0 {
		// Nothing to print for -A/-B/-C case if inverting etc.
		if cfg.HasMaxCount && cfg.MaxCount == 0 {
			return false, nil
		}
		return false, nil
	}

	// apply max-count
	if cfg.HasMaxCount {
		if int64(len(matches)) > cfg.MaxCount {
			matches = matches[:cfg.MaxCount]
		}
	}

	// Print heading if applicable
	printedHeading := false
	if cfg.Heading == 1 && cfg.WithFilename {
		if s.printedAny {
			s.Out.WriteByte('\n')
		}
		s.printHeading(displayPath)
		printedHeading = true
		s.printedAny = true
	}

	printed := make(map[int]bool)
	contextPrinted := false
	for mi, m := range matches {
		// Before-context
		if cfg.BeforeContext > 0 {
			start := m.line - cfg.BeforeContext
			if start < 1 {
				start = 1
			}
			// avoid printing twice
			for ln := start; ln < m.line; ln++ {
				if printed[ln] {
					continue
				}
				if contextPrinted && mi > 0 && ln == start && cfg.AfterContext+cfg.BeforeContext > 0 {
					// separator "--"
					if ln != matches[mi-1].line+1 && !printed[ln-1] {
						if cfg.Heading != 1 || !printedHeading {
							// ripgrep does print "--" separator; see logic
						}
					}
				}
				s.printLine(displayPath, ln, lines[ln-1], nil, 0, printedHeading, true)
				printed[ln] = true
			}
		}
		if !printed[m.line] {
			s.printLine(displayPath, m.line, m.data, m.matches, m.col, printedHeading, false)
			printed[m.line] = true
		}
		// After-context
		if cfg.AfterContext > 0 {
			endLine := m.line + cfg.AfterContext
			if endLine > len(lines) {
				endLine = len(lines)
			}
			for ln := m.line + 1; ln <= endLine; ln++ {
				if printed[ln] {
					continue
				}
				// Don't print if next match line begins
				if mi+1 < len(matches) && ln >= matches[mi+1].line {
					break
				}
				s.printLine(displayPath, ln, lines[ln-1], nil, 0, printedHeading, true)
				printed[ln] = true
				contextPrinted = true
			}
		}
	}

	return true, nil
}

const (
	ansiReset    = "\x1b[0m"
	ansiBoldRed  = "\x1b[1m\x1b[31m"
	ansiMagenta  = "\x1b[35m"
	ansiGreen    = "\x1b[32m"
)

func (s *Searcher) printHeading(path string) {
	if s.UseColor {
		s.Out.WriteString(ansiReset + ansiMagenta + path + ansiReset + "\n")
	} else {
		s.Out.WriteString(path + "\n")
	}
}

func (s *Searcher) writePathPrefix(path string) {
	if s.UseColor {
		s.Out.WriteString(ansiReset + ansiMagenta + path + ansiReset)
	} else {
		s.Out.WriteString(path)
	}
}

func (s *Searcher) printLine(displayPath string, lineNum int, data []byte, matches [][]int, col int, inHeading, isContext bool) {
	cfg := s.Cfg
	sep := cfg.FieldMatchSeparator
	if isContext {
		sep = cfg.FieldContextSeparator
	}

	if !inHeading && cfg.WithFilename {
		s.writePathPrefix(displayPath)
		s.Out.WriteString(sep)
	}
	if cfg.ShowLineNumber {
		if s.UseColor {
			fmt.Fprintf(s.Out, "%s%s%d%s", ansiReset, ansiGreen, lineNum, ansiReset)
		} else {
			fmt.Fprintf(s.Out, "%d", lineNum)
		}
		s.Out.WriteString(sep)
	}
	if cfg.Column && !isContext {
		if s.UseColor {
			fmt.Fprintf(s.Out, "%s%s%d%s", ansiReset, ansiGreen, col, ansiReset)
		} else {
			fmt.Fprintf(s.Out, "%d", col)
		}
		s.Out.WriteString(sep)
	}
	if cfg.ByteOffset {
		fmt.Fprintf(s.Out, "%d%s", 0, sep) // TODO proper byte offset
	}

	if cfg.OnlyMatching && !isContext && !cfg.InvertMatch {
		for _, mm := range matches {
			piece := data[mm[0]:mm[1]]
			if s.UseColor {
				s.Out.WriteString(ansiReset + ansiBoldRed)
				s.Out.Write(piece)
				s.Out.WriteString(ansiReset)
			} else {
				s.Out.Write(piece)
			}
			s.Out.WriteByte('\n')
			// need path/line prefix for each match
			if mm != matches[len(matches)-1] {
				if !inHeading && cfg.WithFilename {
					s.writePathPrefix(displayPath)
					s.Out.WriteString(sep)
				}
				if cfg.ShowLineNumber {
					if s.UseColor {
						fmt.Fprintf(s.Out, "%s%s%d%s", ansiReset, ansiGreen, lineNum, ansiReset)
					} else {
						fmt.Fprintf(s.Out, "%d", lineNum)
					}
					s.Out.WriteString(sep)
				}
			}
		}
		return
	}

	if s.UseColor && !isContext && len(matches) > 0 {
		last := 0
		for _, mm := range matches {
			s.Out.Write(data[last:mm[0]])
			s.Out.WriteString(ansiReset + ansiBoldRed)
			s.Out.Write(data[mm[0]:mm[1]])
			s.Out.WriteString(ansiReset)
			last = mm[1]
		}
		s.Out.Write(data[last:])
	} else {
		s.Out.Write(data)
	}
	s.Out.WriteByte('\n')
}

// runFilesMode prints all files that would be searched.
func runFilesMode(cfg *Config) (int, error) {
	paths := cfg.Paths
	if len(paths) == 0 {
		paths = []string{"."}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	any := false
	for _, root := range paths {
		fi, err := os.Stat(root)
		if err != nil {
			if !cfg.NoMessages {
				fmt.Fprintf(os.Stderr, "rg: %s: %v\n", root, err)
			}
			continue
		}
		if fi.Mode().IsRegular() {
			any = true
			fmt.Fprintln(w, root)
			continue
		}
		var results []string
		filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return nil
			}
			name := info.Name()
			if path != root && strings.HasPrefix(name, ".") && !cfg.Hidden && cfg.Unrestricted < 1 {
				if info.IsDir() {
					return filepath.SkipDir
				}
				return nil
			}
			if info.IsDir() {
				return nil
			}
			displayPath := path
			if root == "." && strings.HasPrefix(displayPath, "./") {
				displayPath = displayPath[2:]
			}
			results = append(results, displayPath)
			return nil
		})
		switch cfg.Sort {
		case "path":
			sort.Strings(results)
		}
		for _, p := range results {
			any = true
			fmt.Fprintln(w, p)
		}
	}
	if any {
		return ExitMatch, nil
	}
	return ExitNoMatch, nil
}

func isStdinPipe() bool {
	fi, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) == 0
}

func isStdoutTTY() bool {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}
