		}
		onlyDir := false
		if strings.HasSuffix(line, "/") {
			onlyDir = true
			line = line[:len(line)-1]
		}
		rooted := false
		if strings.HasPrefix(line, "/") {
			rooted = true
			line = line[1:]
		} else if strings.Contains(line, "/") {
