// Build a chain of gitignore sets from repo root down to dir.
func buildIgnoreChain(repoRoot, dir string) []*ignoreSet {
	var chain []*ignoreSet
	// walk from repoRoot down to dir
	rel, err := filepath.Rel(repoRoot, dir)
	if err != nil {
		return nil
	}
	cur := repoRoot
	// Also check ~/.config/git/ignore? skipped for simplicity.
	// root .gitignore
	if s := tryLoadIgnore(filepath.Join(cur, ".gitignore")); s != nil {
		chain = append(chain, s)
	}
	if rel == "." {
		return chain
	}
	parts := strings.Split(rel, string(os.PathSeparator))
	for _, p := range parts {
		cur = filepath.Join(cur, p)
		if s := tryLoadIgnore(filepath.Join(cur, ".gitignore")); s != nil {
			chain = append(chain, s)
		}
	}
	return chain
}

func tryLoadIgnore(p string) *ignoreSet {
	info, err := os.Stat(p)
	if err != nil || info.IsDir() {
		return nil
	}
	s, err := loadIgnoreFile(p)
	if err != nil {
		return nil
	}
	return s
}

// findGitRoot finds the nearest .git directory, returning its parent.
func findGitRoot(start string) string {
	abs, err := filepath.Abs(start)
	if err != nil {
		return ""
	}
	cur := abs
	for {
		if info, err := os.Stat(filepath.Join(cur, ".git")); err == nil {
			if info.IsDir() || info.Mode().IsRegular() {
				return cur
			}
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			return ""
		}
		cur = parent
	}
}

// pathIgnored decides if a given path (relative to root) is ignored based on chain.
func pathIgnored(chain []*ignoreSet, absPath string, isDir bool) bool {
	ignored := false
	for _, s := range chain {
		// compute relative path from s.baseDir
		rel, err := filepath.Rel(s.baseDir, absPath)
		if err != nil {
			continue
		}
		if strings.HasPrefix(rel, "..") {
			continue
		}
		rel = filepath.ToSlash(rel)
		r, has := s.match(rel, isDir)
		if has {
			ignored = r
		}
	}
	return ignored
}
